import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { Delivery } from "../../../../../models/Delivery";
import type { DeliveryMetricsHistory } from "../../../../../models/Delivery/DeliveryMetricsHistory";
import type { IEntityReference } from "../../../../../models/EntityReference";
import { Feature } from "../../../../../models/Feature";
import DeliverySection, { METRICS_GRID_COLUMNS } from "./DeliverySection";

const {
	mockGetMetricsHistory,
	mockUseLicenseRestrictions,
	mockBurnupChart,
	mockPredictabilityChart,
	mockFeverChart,
	mockEpicSizeChart,
} = vi.hoisted(() => ({
	mockGetMetricsHistory: vi.fn(),
	mockUseLicenseRestrictions: vi.fn(),
	mockBurnupChart: vi.fn((_props: { history: unknown }) => (
		<div data-testid="burnup-chart" />
	)),
	mockPredictabilityChart: vi.fn((_props: { history: unknown }) => (
		<div data-testid="predictability-chart" />
	)),
	mockFeverChart: vi.fn((_props: { history: unknown }) => (
		<div data-testid="fever-chart" />
	)),
	mockEpicSizeChart: vi.fn(
		(_props: { history: unknown; featuresTerm?: string }) => (
			<div data-testid="epic-size-chart" />
		),
	),
}));

const TERMS: Record<string, string> = {
	workItems: "Work Items",
	features: "Epics",
};

vi.mock("../../../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) => TERMS[key] ?? key,
	}),
}));

vi.mock("../../../../../hooks/useLicenseRestrictions", () => ({
	useLicenseRestrictions: mockUseLicenseRestrictions,
}));

vi.mock("../../../../../services/Api/ApiServiceContext", () => ({
	ApiServiceContext: {
		_currentValue: {
			featureService: { getFeatureWorkItems: vi.fn().mockResolvedValue([]) },
			deliveryService: { getMetricsHistory: mockGetMetricsHistory },
		},
	},
}));

vi.mock("../../../../../components/Common/Charts/DeliveryBurnupChart", () => ({
	default: (props: { history: DeliveryMetricsHistory }) =>
		mockBurnupChart(props),
}));

vi.mock(
	"../../../../../components/Common/Charts/DeliveryPredictabilityChart",
	() => ({
		default: (props: { history: DeliveryMetricsHistory }) =>
			mockPredictabilityChart(props),
	}),
);

vi.mock("../../../../../components/Common/Charts/DeliveryFeverChart", () => ({
	default: (props: { history: DeliveryMetricsHistory }) =>
		mockFeverChart(props),
}));

vi.mock(
	"../../../../../components/Common/Charts/DeliveryEpicSizeChart",
	() => ({
		default: (props: {
			history: DeliveryMetricsHistory;
			featuresTerm?: string;
		}) => mockEpicSizeChart(props),
	}),
);

const getHistory = (): DeliveryMetricsHistory => ({
	deliveryDate: new Date("2026-06-10T00:00:00Z"),
	firstSnapshotDate: new Date("2026-06-01T00:00:00Z"),
	points: [
		{
			date: new Date("2026-06-01T00:00:00Z"),
			targetDateAtSnapshot: null,
			totalWork: 20,
			doneWork: 4,
			remainingWork: 16,
			estimatedItemCount: null,
			forecastHowMany: null,
			likelihoodPercentage: null,
			whenDistribution: null,
			featureBreakdown: [],
		},
	],
});

const getMockDelivery = (overrides: Partial<Delivery> = {}): Delivery => {
	const delivery = new Delivery();
	delivery.id = 7;
	delivery.name = "Test Delivery";
	delivery.date = new Date("2026-06-10").toISOString();
	delivery.features = [1];
	delivery.likelihoodPercentage = 75;
	delivery.progress = 60;
	delivery.remainingWork = 4;
	delivery.totalWork = 10;
	delivery.featureLikelihoods = [];
	delivery.completionDates = [];
	delivery.metricSnapshotCount = 3;
	return Object.assign(delivery, overrides);
};

const getMockFeature = (): Feature => {
	const feature = new Feature();
	feature.id = 1;
	feature.name = "Test Feature";
	feature.remainingWork = { "1": 5 };
	feature.totalWork = { "1": 10 };
	feature.forecasts = [];
	return feature;
};

const mockTeams: IEntityReference[] = [{ id: 1, name: "Team Alpha" }];

const renderSection = (deliveryOverrides: Partial<Delivery> = {}) =>
	render(
		<MemoryRouter>
			<DeliverySection
				delivery={getMockDelivery(deliveryOverrides)}
				features={[getMockFeature()]}
				isExpanded={true}
				isLoadingFeatures={false}
				onToggleExpanded={vi.fn()}
				onDelete={vi.fn()}
				onEdit={vi.fn()}
				teams={mockTeams}
			/>
		</MemoryRouter>,
	);

const setPremium = (canUsePremiumFeatures: boolean) => {
	mockUseLicenseRestrictions.mockReturnValue({
		licenseStatus: { canUsePremiumFeatures },
	});
};

describe("DeliverySection Metrics tab", () => {
	beforeEach(() => {
		mockGetMetricsHistory.mockReset();
		mockBurnupChart.mockClear();
		mockPredictabilityChart.mockClear();
		mockFeverChart.mockClear();
		mockGetMetricsHistory.mockResolvedValue(getHistory());
	});

	it("offers the Metrics tab to community users without a premium license", () => {
		setPremium(false);
		renderSection();
		expect(screen.getByRole("tab", { name: "Metrics" })).toBeInTheDocument();
	});

	it("renders the burnup chart for community users without a premium license", async () => {
		setPremium(false);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});
	});

	it("does not fetch metrics history while the Work Items tab is active", () => {
		setPremium(true);
		renderSection();
		expect(mockGetMetricsHistory).not.toHaveBeenCalled();
	});

	it("does not render the burnup chart while the Work Items tab is the active one", () => {
		setPremium(true);
		renderSection();

		expect(screen.getByRole("tab", { name: "Work Items" })).toHaveAttribute(
			"aria-selected",
			"true",
		);
		expect(screen.queryByTestId("burnup-chart")).not.toBeInTheDocument();
	});

	it("removes the burnup chart again when returning to the Work Items tab", async () => {
		setPremium(true);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));
		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});

		fireEvent.click(screen.getByRole("tab", { name: "Work Items" }));

		expect(screen.queryByTestId("burnup-chart")).not.toBeInTheDocument();
	});

	it("does not fetch metrics when the active tab is switched to a non-Metrics tab", () => {
		setPremium(true);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Work Items" }));

		expect(screen.getByRole("tab", { name: "Work Items" })).toHaveAttribute(
			"aria-selected",
			"true",
		);
		expect(mockGetMetricsHistory).not.toHaveBeenCalled();
	});

	it("lazily fetches metrics history for the delivery on the first Metrics-tab open", async () => {
		setPremium(true);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(mockGetMetricsHistory).toHaveBeenCalledWith(7);
		});
		expect(mockGetMetricsHistory).toHaveBeenCalledTimes(1);
	});

	it("renders the burnup chart with the fetched history once Metrics is opened", async () => {
		setPremium(true);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});
		expect(mockBurnupChart).toHaveBeenCalledWith(
			expect.objectContaining({ history: getHistory() }),
		);
	});

	it("renders the burnup, predictability and fever charts together from the same fetched history", async () => {
		setPremium(false);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});
		expect(screen.getByTestId("predictability-chart")).toBeInTheDocument();
		expect(screen.getByTestId("fever-chart")).toBeInTheDocument();
		expect(mockGetMetricsHistory).toHaveBeenCalledTimes(1);
		expect(mockPredictabilityChart).toHaveBeenCalledWith(
			expect.objectContaining({ history: getHistory() }),
		);
		expect(mockFeverChart).toHaveBeenCalledWith(
			expect.objectContaining({ history: getHistory() }),
		);
	});

	it("shows a loading placeholder while the metrics history is still in flight", async () => {
		setPremium(true);
		let resolveFetch!: (value: DeliveryMetricsHistory) => void;
		mockGetMetricsHistory.mockReturnValue(
			new Promise<DeliveryMetricsHistory>((resolve) => {
				resolveFetch = resolve;
			}),
		);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		expect(screen.getByText("Loading metrics...")).toBeInTheDocument();
		expect(screen.queryByTestId("burnup-chart")).not.toBeInTheDocument();

		resolveFetch(getHistory());
		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});
	});

	it("fetches metrics history only once across repeated tab switches", async () => {
		setPremium(true);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));
		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});

		fireEvent.click(screen.getByRole("tab", { name: "Work Items" }));
		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
		});
		expect(mockGetMetricsHistory).toHaveBeenCalledTimes(1);
	});
});

describe("DeliverySection Metrics tab snapshot gating", () => {
	beforeEach(() => {
		mockGetMetricsHistory.mockReset();
		mockGetMetricsHistory.mockResolvedValue(getHistory());
		setPremium(true);
	});

	it("disables the Metrics tab with an explanatory tooltip while too few snapshots are recorded", async () => {
		renderSection({ metricSnapshotCount: 2 });

		const metricsTab = screen.getByRole("tab", { name: /Metrics/ });
		expect(metricsTab).toBeDisabled();

		fireEvent.mouseOver(screen.getByText("Metrics"));

		await waitFor(() => {
			expect(
				screen.getByText(
					"Metrics need at least 3 daily records to chart trends (have 2).",
				),
			).toBeInTheDocument();
		});
	});

	it("enables the Metrics tab once enough snapshots are recorded", () => {
		renderSection({ metricSnapshotCount: 3 });

		expect(screen.getByRole("tab", { name: /Metrics/ })).not.toBeDisabled();
	});

	it("does not fetch metrics or switch tabs when the disabled Metrics tab is clicked", () => {
		renderSection({ metricSnapshotCount: 0 });

		fireEvent.click(screen.getByRole("tab", { name: /Metrics/ }));

		expect(screen.getByRole("tab", { name: "Work Items" })).toHaveAttribute(
			"aria-selected",
			"true",
		);
		expect(mockGetMetricsHistory).not.toHaveBeenCalled();
		expect(screen.queryByTestId("burnup-chart")).not.toBeInTheDocument();
	});
});

const CARD_ORDER = [
	"burnup-chart",
	"predictability-chart",
	"epic-size-chart",
	"fever-chart",
];

const openMetricsTab = async (): Promise<void> => {
	fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));
	await waitFor(() => {
		expect(screen.getByTestId("burnup-chart")).toBeInTheDocument();
	});
};

describe("DeliverySection Metrics tab layout", () => {
	beforeEach(() => {
		mockGetMetricsHistory.mockReset();
		mockEpicSizeChart.mockClear();
		mockGetMetricsHistory.mockResolvedValue(getHistory());
		setPremium(true);
	});

	it("shows the epic size and count card built from the same fetched history (AC-1.3)", async () => {
		renderSection();
		await openMetricsTab();

		expect(screen.getByTestId("epic-size-chart")).toBeInTheDocument();
		expect(mockEpicSizeChart).toHaveBeenCalledWith(
			expect.objectContaining({ history: getHistory() }),
		);
	});

	it("reads the four cards burnup, predictability, epic size and count, fever (AC-1.3)", async () => {
		renderSection();
		await openMetricsTab();

		const grid = screen.getByTestId("delivery-metrics-grid");
		const order = Array.from(grid.children).map((child) =>
			CARD_ORDER.find(
				(testId) => child.querySelector(`[data-testid="${testId}"]`) !== null,
			),
		);

		expect(order).toEqual(CARD_ORDER);
	});

	it("gives each of the four cards its own cell so none spans the whole row (AC-1.3)", async () => {
		renderSection();
		await openMetricsTab();

		const grid = screen.getByTestId("delivery-metrics-grid");
		expect(grid.children).toHaveLength(CARD_ORDER.length);
		expect(window.getComputedStyle(grid).display).toBe("grid");
	});

	it("pairs the cards on a wide screen and stacks them on a narrow one (AC-1.4)", () => {
		expect(METRICS_GRID_COLUMNS).toEqual({ xs: "1fr", lg: "1fr 1fr" });
	});

	it("hands the chart this instance's word for epics (AC-1.5)", async () => {
		renderSection();
		await openMetricsTab();

		expect(mockEpicSizeChart).toHaveBeenCalledWith(
			expect.objectContaining({ featuresTerm: "Epics" }),
		);
	});

	it("names the card's enlarge control after the same term", async () => {
		renderSection();
		await openMetricsTab();

		expect(
			screen.getByRole("button", { name: "Enlarge Epics over Time" }),
		).toBeInTheDocument();
	});

	it("keeps the placeholder up when the delivery has no metrics to show", async () => {
		mockGetMetricsHistory.mockResolvedValue(null);
		renderSection();

		fireEvent.click(screen.getByRole("tab", { name: "Metrics" }));

		await waitFor(() => {
			expect(mockGetMetricsHistory).toHaveBeenCalled();
		});
		expect(screen.getByText("Loading metrics...")).toBeInTheDocument();
		expect(screen.queryByTestId("epic-size-chart")).not.toBeInTheDocument();
	});
});

